// Capturamos el cuerpo del webhook
const body = items[0].json.body || items[0].json;

// 1. Buscamos el nombre tanto en 'name' como en 'nombre'
let nombre = body.name || body.nombre || "";

// 2. Si hay nombre, lo capitalizamos. Si no, lo dejamos vacío 
// para que la IA sepa que no lo tiene y use el saludo de empresa.
if (nombre && nombre.toLowerCase() !== 'cliente') {
  nombre = nombre.charAt(0).toUpperCase() + nombre.slice(1);
} else {
  nombre = ""; 
}

// 3. Normalizamos el resto de campos para el AI Agent
const business = body.business || "";
const pain_point = body.pain_point || body.message || body.mensaje || "";

return [
  {
    json: {
      nombre: nombre,
      email: body.email,
      business: business,
      pain_point: pain_point,
      fecha: new Date().toISOString()
    }
  }
];

// 1. Cogemos la salida de la IA
let ai_text = $input.item.json.output;
ai_text = ai_text.replace(/```json/g, '').replace(/```/g, '').trim();

// 2. Cogemos los datos que vienen del nodo inmediatamente anterior (la IA)
// Pero n8n nos permite acceder a los datos de "atrás" fácilmente
const datos_limpios = $node["Limpieza de Datos"].json;

try {
    const ai_data = JSON.parse(ai_text);
    return {
        ...datos_limpios, // Aquí va el Nombre y el Email
        "Score": ai_data.score || ai_data.Score || "REGULAR",
        "Investigacion_IA": ai_data.resumen || ai_data.resumen || "Investigación completada."
    };
} catch (e) {
    return {
        ...datos_limpios,
        "Score": "ERROR",
        "Investigacion_IA": "Error: " + ai_text.substring(0, 50)
    };
}
